#!/usr/bin/env python3
"""Bounded public research captures, with exact source metadata and compressed bytes."""
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
import datetime,gzip,hashlib,json,requests,subprocess,tempfile
ROOT=Path(__file__).resolve().parent
URLS={'wlbt-results': 'https://www.wlbt.com/politics/election-results/', 'wlox-results': 'https://www.wlox.com/politics/election-results/', 'wtva-home': 'https://www.wtva.com/', 'sos-results': 'https://www.sos.ms.gov/elections-voting/election-results', 'nyt-elections': 'https://www.nytimes.com/section/politics/elections', 'wdam-results': 'https://www.wdam.com/politics/election-results/', 'wdam-democrat-coverage': 'https://www.wdam.com/politics/democrat/', 'mpb-home': 'https://www.mpbonline.org/', 'sos-2022-certified-index': 'https://www.sos.ms.gov/elections/electionresults_aspx/elections_results_2022_certified.aspx', 'sos-2024-general-index': 'https://www.sos.ms.gov/elections-voting/election-results/2024/2024-general-election-results', 'sos-2020-general-index': 'https://www.sos.ms.gov/elections-voting/election-results/2020/2020-general-election', 'sos-2018-general-index': 'https://www.sos.ms.gov/elections-voting/election-results/2018/2018-general-election', 'sos-2018-runoff-index': 'https://www.sos.ms.gov/elections-voting/election-results/2018/2018-general-election-runoff', 'sos-2024-iframe': 'https://sos.ms.gov/elections/electionresults_aspx/elections_results_2024_general.aspx', 'sos-2020-iframe': 'https://sos.ms.gov/elections/electionresults_aspx/elections_results_2020_general.aspx', 'sos-2018-iframe': 'https://sos.ms.gov/elections/electionresults_aspx/elections_results_2018_general.aspx', 'sos-2018-runoff-iframe': 'https://sos.ms.gov/elections/electionresults_aspx/elections_results_2018_grunoff.aspx', 'sos-2024-recap-csv': 'https://www.sos.ms.gov/elections/electionresults/2024ElectionRecapSheets.csv', 'sos-2024-recap-pdf': 'https://www.sos.ms.gov/elections/electionresults/2024%20Official%20Statewide%20Results.pdf', 'sos-2024-certified-index': 'https://www.sos.ms.gov/elections/electionresults_aspx/elections_results_2024_certified.aspx', 'sos-2020-recap-csv': 'http://www.sos.ms.gov/elections/electionresults/2020%20General%20Election%20Official%20Statewide%20Recapitulation%20(CSV).csv', 'sos-2020-certified-index': 'https://www.sos.ms.gov/elections/electionresults_aspx/elections_results_2020_certified.aspx', 'sos-2018-certified-index': 'https://www.sos.ms.gov/elections/electionresults_aspx/elections_results_2018_Gcertified.aspx', 'sos-2018-runoff-certified-index': 'https://www.sos.ms.gov/elections/electionresults_aspx/elections_results_2018_CertifiedRunoff.aspx', 'sos-2024-certified-pres-pdf': 'https://www.sos.ms.gov/elections/electionresults/2024General/Statewide%20Results/Certification%20of%20Vote%20for%20Electors%20for%20President%20and%20Vice%20President.pdf', 'sos-2024-certified-sen-pdf': 'https://www.sos.ms.gov/elections/electionresults/2024General/Statewide%20Results/Certification%20of%20Vote%20for%20United%20States%20Senate.pdf', 'sos-2020-certified-sen-pdf': 'https://www.sos.ms.gov/elections/electionresults/2020General/Statewide%20Certified%20Results/US%20Senate.pdf', 'sos-2020-amended-sen-pdf': 'https://www.sos.ms.gov/elections/electionresults/2020General/Statewide%20Certified%20Results/US%20Senate_AMENDED.pdf', 'sos-2018-runoff-certified-sen-pdf': 'https://www.sos.ms.gov/elections/electionresults/2018GeneralRunoff/Certified%20Results/United%20States%20Senate%20Special.pdf', 'sos-2024-county-recap-index': 'https://www.sos.ms.gov/elections/electionresults_aspx/elections_results_2024_county.aspx', 'sos-2018-special-parent': 'https://www.sos.ms.gov/elections-voting/election-results/2018/2018-special-election', 'sos-2018-special-iframe': 'https://sos.ms.gov/elections/electionresults_aspx/elections_results_2018_specialall.aspx', 'sos-2024-county-hinds': 'https://www.sos.ms.gov/elections/electionresults/2024General/County%20Results/Hinds.pdf', 'sos-2024-county-madison': 'https://www.sos.ms.gov/elections/electionresults/2024General/County%20Results/Madison.pdf', 'sos-2018-general-certified-sen-pdf': 'https://www.sos.ms.gov/elections/electionresults/2018General/Certified%20Results/United%20States%20Senate.pdf', 'sos-2018-general-county-index': 'https://sos.ms.gov/elections/electionresults_aspx/elections_results_2018_Gcounty.aspx', 'wtok-results': 'https://www.wtok.com/politics/election-results/', 'wtok-politics': 'https://www.wtok.com/politics/', 'delta-home': 'https://www.deltanews.tv/', 'mpb-voter-guide': 'https://www.mpbonline.org/election/voter-guide/', 'mpb-2025-counting-report': 'https://www.mpbonline.org/blogs/news/mississippi-2025-special-elections-results/', 'wtva-results': 'https://www.wtva.com/politics/election-results/', 'delta-political': 'https://www.deltanews.tv/news/political/', 'mpb-guide-branch-shell': 'https://www.branch.vote/embedded-lookup?organization=mpbonline&election=2026-mississippi-general-election', 'sos-current-qualifying': 'https://www.sos.ms.gov/content/CandidateQualifying/default.aspx', 'delta-2026-levee-results': 'https://www.deltanews.tv/news/2026-levee-board-election-results/article_6c78c7f9-d47a-4d2d-9da5-61714082da95.html', 'delta-washington-administration': 'https://www.deltanews.tv/news/washington-county-election-officials-warn-of-growing-voter-inactivity/article_8a1a7ee6-dd1d-4cf3-ae01-67370c395c92.html', 'sos-2024-county-coahoma-updated': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/Coahoma Updated.pdf', 'sos-2024-county-coahoma': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/Coahoma.pdf', 'sos-2024-county-pike-updated': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/Pike Updated.pdf', 'sos-2024-county-pike': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/Pike.pdf', 'sos-2024-county-harrison': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/Harrison.pdf', 'sos-2024-county-jackson': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/Jackson.pdf', 'sos-2024-county-desoto': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/DeSoto.pdf', 'sos-2024-county-lauderdale': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/Lauderdale.pdf', 'sos-2024-county-forrest': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/Forrest.pdf', 'sos-2024-county-lee': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/Lee.pdf', 'sos-2024-county-rankin': 'https://www.sos.ms.gov/elections/electionresults/2024General/County Results/Rankin.pdf'}
def fetch(item):
 key,url=item;row={'id':key,'url':url,'retrieved_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()}
 try:
  r=requests.get(url,timeout=35);path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(r.content,mtime=0))
  row.update(status=r.status_code,final_url=r.url,raw_sha256=hashlib.sha256(r.content).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(r.content),headers=dict(r.headers))
 except requests.exceptions.SSLError as e:
  row['requests_error']=str(e)
  with tempfile.TemporaryDirectory() as t:
   body=Path(t)/'body';hdr=Path(t)/'headers'
   c=subprocess.run(['curl','--silent','--show-error','--location','--max-time','35','--dump-header',str(hdr),'--output',str(body),'--write-out','%{http_code}\\n%{url_effective}',url],capture_output=True,text=True)
   row['transport']='system curl with default certificate verification'
   if c.returncode==0:
    code,final=c.stdout.split('\\n',1) if '\\n' in c.stdout else c.stdout.split('\n',1)
    raw=body.read_bytes();path=ROOT/(key+'.html.gz');path.write_bytes(gzip.compress(raw,mtime=0))
    row.update(status=int(code),final_url=final,raw_sha256=hashlib.sha256(raw).hexdigest(),asset=path.name,stored_sha256=hashlib.sha256(path.read_bytes()).hexdigest(),bytes=len(raw),raw_headers=hdr.read_text())
   else:row['error']=c.stderr
 except requests.RequestException as e:row['error']=str(e)
 return row
if __name__=='__main__':
 rows=list(ThreadPoolExecutor(max_workers=4).map(fetch,URLS.items()));(ROOT/'manifest.json').write_text(json.dumps(rows,indent=2)+'\n')
 for r in rows:print(r['id'],r.get('status',r.get('error')))
